def body_qs():
    out=[]
    for org,f in ORG:
        out.append((f"ما الوظيفة الرئيسية لعضو {org}؟",o(f,[x for _,x in ORG])))
        out.append((f"أي عضو وظيفته الرئيسية «{f}»؟",o(org,[x for x,_ in ORG])))
    for v,d in VIT: out.append((f"ما المرض الذي يسببه نقص {v}؟",o(d,[x for _,x in VIT])))
    for v,s in VSRC: out.append((f"ما المصدر المشهور لـ{v}؟",o(s,[x for _,x in VSRC])))
    for d,b in BONES: out.append((f"ما {d}؟",o(b,[x for _,x in BONES])))
    for s,f in SENSE:
        out.append((f"ما الحاسة المرتبطة بعضو {s}؟",o(f,[x for _,x in SENSE])))
        out.append((f"ما العضو المسؤول عن حاسة {f}؟",o(s,[x for x,_ in SENSE])))
    for s,org in SYS:
        out.append((f"ما العضو الرئيسي في {s}؟",o(org,[x for _,x in SYS])))
        out.append((f"إلى أي جهاز ينتمي عضو {org}؟",o(s,[x for x,_ in SYS])))
    out+=[(q,[a]+d) for q,a,d in NUM]
    out+=[(q,o(a,d)) for q,a,d in MISC]
    return out
